def transform(g):
    from collections import Counter, deque
    h,w=len(g),len(g[0]); bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]; seen=set()
    for y in range(h):
      for x in range(w):
       if (y,x) in seen or g[y][x]==bg: continue
       c=g[y][x]; q=deque([(y,x)]); seen.add((y,x)); comp=[]
       while q:
        a,b=q.popleft(); comp.append((a,b))
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
         aa,bb=a+da,b+db
         if 0<=aa<h and 0<=bb<w and (aa,bb) not in seen and g[aa][bb]==c:
          seen.add((aa,bb));q.append((aa,bb))
       ys=[a for a,b in comp]; xs=[b for a,b in comp]
       t,b=min(ys),max(ys); l,r=min(xs),max(xs); area=(b-t+1)*(r-l+1)
       if area>=6 and len(comp)/area>=0.65:
        for a in range(t,b+1):
         for z in range(l,r+1): out[a][z]=c
    return out

